-- 008_add_itinerary_fields.sql
-- ============================================================
-- Migration: Add itinerary planning fields to cards table
-- Description: Adds day, time_slot, order, and travel_info columns to support itinerary planning features
-- Created: 2025-12-26

-- Add itinerary planning fields to cards table
ALTER TABLE cards
  ADD COLUMN IF NOT EXISTS day INTEGER,
  ADD COLUMN IF NOT EXISTS time_slot TEXT,
  ADD COLUMN IF NOT EXISTS "order" INTEGER,
  ADD COLUMN IF NOT EXISTS travel_info JSONB DEFAULT NULL;

-- Add indexes for efficient querying
CREATE INDEX IF NOT EXISTS idx_cards_day
  ON cards(day)
  WHERE day IS NOT NULL;

CREATE INDEX IF NOT EXISTS idx_cards_trip_day
  ON cards(trip_id, day);

CREATE INDEX IF NOT EXISTS idx_cards_trip_day_order
  ON cards(trip_id, day, "order")
  WHERE day IS NOT NULL;

-- Add constraints
ALTER TABLE cards
  ADD CONSTRAINT cards_day_check
  CHECK (day IS NULL OR (day >= 1 AND day <= 365));

ALTER TABLE cards
  ADD CONSTRAINT cards_order_check
  CHECK ("order" IS NULL OR "order" >= 0);

-- Create function to validate time slot format (HH:MM 24-hour)
CREATE OR REPLACE FUNCTION validate_time_slot(slot TEXT)
RETURNS BOOLEAN AS $$
BEGIN
  -- Format: HH:MM (24-hour)
  RETURN slot ~ '^([0-1][0-9]|2[0-3]):[0-5][0-9]$';
END;
$$ LANGUAGE plpgsql IMMUTABLE;

-- Add time slot format constraint
ALTER TABLE cards
  ADD CONSTRAINT cards_time_slot_format
  CHECK (time_slot IS NULL OR validate_time_slot(time_slot));

-- Create function to update updated_at timestamp
CREATE OR REPLACE FUNCTION update_updated_at_column()
RETURNS TRIGGER AS $$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Add trigger to update updated_at on any change
DROP TRIGGER IF EXISTS update_cards_updated_at ON cards;
CREATE TRIGGER update_cards_updated_at
  BEFORE UPDATE ON cards
  FOR EACH ROW
  EXECUTE FUNCTION update_updated_at_column();

-- Add column comments for documentation
COMMENT ON COLUMN cards.day IS 'Which day of the trip (1-based index, 1-365)';
COMMENT ON COLUMN cards.time_slot IS 'Scheduled time in HH:MM format (24-hour)';
COMMENT ON COLUMN cards."order" IS 'Position within the day (0-based)';
COMMENT ON COLUMN cards.travel_info IS 'Travel details to next stop: {distance, duration, mode, next_stop_id}';

-- Rollback script (for reference, commented out)
/*
-- To rollback this migration, run:
ALTER TABLE cards
  DROP COLUMN IF EXISTS day,
  DROP COLUMN IF EXISTS time_slot,
  DROP COLUMN IF EXISTS "order",
  DROP COLUMN IF EXISTS travel_info;

DROP INDEX IF EXISTS idx_cards_day;
DROP INDEX IF EXISTS idx_cards_trip_day;
DROP INDEX IF EXISTS idx_cards_trip_day_order;
DROP FUNCTION IF EXISTS validate_time_slot(TEXT);
DROP TRIGGER IF EXISTS update_cards_updated_at ON cards;
DROP FUNCTION IF EXISTS update_updated_at_column();
*/

-- ============================================================
-- 009_city_videos_cache.sql
-- ============================================================
-- City Videos Cache Migration
-- Persistent database cache for YouTube video search results
-- Reduces API calls and provides instant results for repeat city searches

-- ============================================
-- Table 1: city_videos (Parent - Cache Metadata)
-- ============================================
CREATE TABLE IF NOT EXISTS city_videos (
  city_key TEXT PRIMARY KEY,                    -- "tokyo_35.6762_139.6503"
  city_name TEXT NOT NULL,                      -- "Tokyo"
  country TEXT,
  coordinates JSONB,                            -- { lat, lng }

  fetched_at TIMESTAMPTZ DEFAULT NOW(),         -- When videos were fetched
  expires_at TIMESTAMPTZ NOT NULL,              -- When cache expires (TTL)

  fetch_count INTEGER DEFAULT 1,                -- Popularity tracking

  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Indexes for city_videos
CREATE INDEX IF NOT EXISTS idx_city_videos_city_name ON city_videos(city_name);
CREATE INDEX IF NOT EXISTS idx_city_videos_expires_at ON city_videos(expires_at);
CREATE INDEX IF NOT EXISTS idx_city_videos_fetch_count ON city_videos(fetch_count DESC);

-- ============================================
-- Table 2: city_video_items (Child - Individual Videos)
-- ============================================
CREATE TABLE IF NOT EXISTS city_video_items (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  city_key TEXT NOT NULL REFERENCES city_videos(city_key) ON DELETE CASCADE,

  video_id TEXT NOT NULL,                       -- YouTube videoId
  title TEXT,
  description TEXT,
  thumbnail_url TEXT,
  channel_title TEXT,
  published_at TIMESTAMPTZ,

  duration_seconds INTEGER NOT NULL DEFAULT 0,  -- Video duration in seconds
  video_type TEXT NOT NULL DEFAULT 'medium',    -- 'short' | 'medium' | 'long'
  score FLOAT DEFAULT 0,                        -- Ranking score
  source TEXT DEFAULT 'youtube',                -- 'youtube' | 'pexels'

  view_count BIGINT,                            -- For re-scoring
  like_count BIGINT,

  created_at TIMESTAMPTZ DEFAULT NOW(),

  -- Ensure unique video per city
  CONSTRAINT unique_video_per_city UNIQUE (city_key, video_id),
  -- Validate video_type
  CONSTRAINT valid_video_type CHECK (video_type IN ('short', 'medium', 'long'))
);

-- Indexes for city_video_items
CREATE INDEX IF NOT EXISTS idx_city_video_items_city_key ON city_video_items(city_key);
CREATE INDEX IF NOT EXISTS idx_city_video_items_video_type ON city_video_items(video_type);
CREATE INDEX IF NOT EXISTS idx_city_video_items_score ON city_video_items(score DESC);
CREATE INDEX IF NOT EXISTS idx_city_video_items_city_type ON city_video_items(city_key, video_type);

-- ============================================
-- Triggers
-- ============================================

-- Apply updated_at trigger to city_videos
DROP TRIGGER IF EXISTS update_city_videos_updated_at ON city_videos;
CREATE TRIGGER update_city_videos_updated_at
  BEFORE UPDATE ON city_videos
  FOR EACH ROW
  EXECUTE FUNCTION update_updated_at_column();

-- ============================================
-- Row Level Security
-- ============================================
-- Note: City videos are public cache data, but we still enable RLS
-- for security. All users can read, only service role can write.

ALTER TABLE city_videos ENABLE ROW LEVEL SECURITY;
ALTER TABLE city_video_items ENABLE ROW LEVEL SECURITY;

-- Anyone can read cached videos (public cache)
CREATE POLICY city_videos_select_all ON city_videos
  FOR SELECT USING (true);

CREATE POLICY city_video_items_select_all ON city_video_items
  FOR SELECT USING (true);

-- Only service role can insert/update/delete (via API routes)
-- Authenticated users cannot directly modify cache
CREATE POLICY city_videos_service_insert ON city_videos
  FOR INSERT WITH CHECK (auth.role() = 'service_role');

CREATE POLICY city_videos_service_update ON city_videos
  FOR UPDATE USING (auth.role() = 'service_role');

CREATE POLICY city_videos_service_delete ON city_videos
  FOR DELETE USING (auth.role() = 'service_role');

CREATE POLICY city_video_items_service_insert ON city_video_items
  FOR INSERT WITH CHECK (auth.role() = 'service_role');

CREATE POLICY city_video_items_service_update ON city_video_items
  FOR UPDATE USING (auth.role() = 'service_role');

CREATE POLICY city_video_items_service_delete ON city_video_items
  FOR DELETE USING (auth.role() = 'service_role');

-- ============================================
-- Grant Permissions
-- ============================================
GRANT SELECT ON city_videos TO anon, authenticated;
GRANT SELECT ON city_video_items TO anon, authenticated;
GRANT ALL ON city_videos TO service_role;
GRANT ALL ON city_video_items TO service_role;

-- ============================================
-- Helper function to calculate dynamic TTL
-- ============================================
CREATE OR REPLACE FUNCTION calculate_video_ttl(p_fetch_count INTEGER)
RETURNS INTERVAL AS $$
BEGIN
  -- Very popular cities (>200 fetches): 7 days
  IF p_fetch_count > 200 THEN
    RETURN INTERVAL '7 days';
  -- Popular cities (>50 fetches): 14 days
  ELSIF p_fetch_count > 50 THEN
    RETURN INTERVAL '14 days';
  -- Default: 30 days
  ELSE
    RETURN INTERVAL '30 days';
  END IF;
END;
$$ LANGUAGE plpgsql IMMUTABLE;

-- ============================================
-- Function to upsert city videos
-- ============================================
CREATE OR REPLACE FUNCTION upsert_city_videos(
  p_city_key TEXT,
  p_city_name TEXT,
  p_country TEXT,
  p_coordinates JSONB,
  p_ttl_days INTEGER DEFAULT 30
)
RETURNS city_videos AS $$
DECLARE
  v_result city_videos;
BEGIN
  INSERT INTO city_videos (city_key, city_name, country, coordinates, expires_at)
  VALUES (
    p_city_key,
    p_city_name,
    p_country,
    p_coordinates,
    NOW() + (p_ttl_days || ' days')::INTERVAL
  )
  ON CONFLICT (city_key) DO UPDATE SET
    city_name = EXCLUDED.city_name,
    country = EXCLUDED.country,
    coordinates = EXCLUDED.coordinates,
    fetched_at = NOW(),
    expires_at = NOW() + (p_ttl_days || ' days')::INTERVAL,
    fetch_count = city_videos.fetch_count + 1,
    updated_at = NOW()
  RETURNING * INTO v_result;

  RETURN v_result;
END;
$$ LANGUAGE plpgsql;

-- ============================================================
-- 010_saved_places.sql
-- ============================================================
-- Saved places: the places a signed-in user has bookmarked while exploring.
-- The app (src/app/api/travel/saved-places) already reads and writes this table.

CREATE TABLE IF NOT EXISTS saved_places (
  user_id    UUID        NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  place_id   TEXT        NOT NULL,
  place_data JSONB,
  saved_at   TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  PRIMARY KEY (user_id, place_id)
);

CREATE INDEX IF NOT EXISTS idx_saved_places_user ON saved_places(user_id, saved_at DESC);

ALTER TABLE saved_places ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS saved_places_own ON saved_places;
CREATE POLICY saved_places_own ON saved_places
  FOR ALL
  USING (auth.uid() = user_id)
  WITH CHECK (auth.uid() = user_id);

-- ============================================================
-- 011_security_fixes.sql
-- ============================================================
-- Security fixes found while preparing for production. Safe to run on a fresh project or on top of 001-010.
--
--  1. The "Admins can view all users" policy selected from `users` inside a policy ON `users`, which makes
--     Postgres fail with "infinite recursion detected in policy for relation users" on every read of that table.
--     Admin checks now go through a SECURITY DEFINER function that bypasses RLS.
--  2. Users could UPDATE their own row, including `role`, and make themselves admin. Role changes are now
--     only possible for admins, the service role, or direct SQL (no end-user session).
--  3. Trips, messages, cards and comments were readable by EVERY user as soon as the trip had one share link,
--     and editable by every user once it had an editor link. Access is now owner-only.
--     Shared links are served by the server (service role) after it validates the token.

-- ---------------------------------------------------------------------------
-- 1. Admin check without recursion
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.is_admin()
RETURNS BOOLEAN
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT EXISTS (SELECT 1 FROM public.users WHERE id = auth.uid() AND role = 'admin');
$$;

REVOKE ALL ON FUNCTION public.is_admin() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.is_admin() TO anon, authenticated, service_role;

DROP POLICY IF EXISTS "Admins can view all users" ON users;
CREATE POLICY "Admins can view all users" ON users
  FOR SELECT USING (auth.uid() = id OR public.is_admin());

DROP POLICY IF EXISTS "Admins can view all feedback" ON feedback;
CREATE POLICY "Admins can view all feedback" ON feedback
  FOR SELECT USING (public.is_admin());

DROP POLICY IF EXISTS "Admins can update feedback" ON feedback;
CREATE POLICY "Admins can update feedback" ON feedback
  FOR UPDATE USING (public.is_admin());

DROP POLICY IF EXISTS "Anyone can view active products" ON products;
CREATE POLICY "Anyone can view active products" ON products
  FOR SELECT USING (is_active = true OR public.is_admin());

DROP POLICY IF EXISTS "Admins can manage products" ON products;
CREATE POLICY "Admins can manage products" ON products
  FOR ALL USING (public.is_admin());

-- ---------------------------------------------------------------------------
-- 2. Nobody can promote themselves to admin
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.protect_user_role()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  -- auth.uid() is NULL for the SQL editor and for the service role, so you can still set the first admin with:
  --   UPDATE users SET role = 'admin' WHERE email = 'you@example.com';
  IF NEW.role IS DISTINCT FROM OLD.role AND auth.uid() IS NOT NULL AND NOT public.is_admin() THEN
    NEW.role := OLD.role;
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS users_protect_role ON users;
CREATE TRIGGER users_protect_role
  BEFORE UPDATE ON users
  FOR EACH ROW EXECUTE FUNCTION public.protect_user_role();

-- ---------------------------------------------------------------------------
-- 3. Owner-only access to trips and everything inside them
-- ---------------------------------------------------------------------------
DROP POLICY IF EXISTS trips_select_own ON trips;
CREATE POLICY trips_select_own ON trips FOR SELECT USING (auth.uid() = user_id);

-- messages_select (as redefined in 007): trip owner, or the owner of the chat conversation
DROP POLICY IF EXISTS messages_select ON messages;
CREATE POLICY messages_select ON messages FOR SELECT USING (
  trip_id IN (SELECT id FROM trips WHERE user_id = auth.uid())
  OR conversation_id IN (SELECT id FROM chat_conversations WHERE user_id = auth.uid())
);

DROP POLICY IF EXISTS cards_select ON cards;
CREATE POLICY cards_select ON cards FOR SELECT USING (
  trip_id IN (SELECT id FROM trips WHERE user_id = auth.uid())
);

DROP POLICY IF EXISTS cards_update ON cards;
CREATE POLICY cards_update ON cards FOR UPDATE USING (
  trip_id IN (SELECT id FROM trips WHERE user_id = auth.uid())
);

DROP POLICY IF EXISTS comments_select ON comments;
CREATE POLICY comments_select ON comments FOR SELECT USING (
  (parent_type = 'message' AND parent_id IN (
    SELECT id FROM messages WHERE trip_id IN (SELECT id FROM trips WHERE user_id = auth.uid())
  ))
  OR
  (parent_type = 'card' AND parent_id IN (
    SELECT id FROM cards WHERE trip_id IN (SELECT id FROM trips WHERE user_id = auth.uid())
  ))
);

-- ============================================================
-- 012_video_insights_cache.sql
-- ============================================================
-- Shared cache for what the AI read out of a YouTube video (summary, key points, tips, named places).
-- One AI call per video for everyone, instead of one per server instance. Only the server (service role) touches
-- this table: RLS is on and there are deliberately no policies, so the browser can neither read nor write it.

CREATE TABLE IF NOT EXISTS video_insights (
  video_id       TEXT        PRIMARY KEY,
  insights       JSONB       NOT NULL,
  has_transcript BOOLEAN     NOT NULL DEFAULT FALSE,
  model          TEXT,
  created_at     TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  expires_at     TIMESTAMPTZ NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_video_insights_expires_at ON video_insights(expires_at);

ALTER TABLE video_insights ENABLE ROW LEVEL SECURITY;
